# Rapports d'alarme de Sécurité Incendie National importés avant que leurs
# codes S-536 existent : on remet leurs codes d'origine.
VERS_S536 = {"FDL": "EOL", "DFG": "DS", "IDG": "FS", "TEL": "ET", "ISO": "EM", "K/S": "VH"}
LEGENDE_VERS_S536 = {**VERS_S536, "C": "B"}
CODES_S536 = {"RI", "DS", "SFD", "FS", "SS", "EM", "H", "V", "SP", "HSP", "AD", "ET", "EOL", "VH"}


def remettre_codes_s536(apps, schema_editor):
    Dispositif = apps.get_model("inspections", "Dispositif")
    FicheLegende = apps.get_model("inspections", "FicheLegende")
    sin = {"rapport__batiment__client__organisation__gabarit_rapports": "sin"}

    for ancien, nouveau in VERS_S536.items():
        Dispositif.objects.filter(type_dispositif=ancien, **sin).update(type_dispositif=nouveau)
    # Codes inconnus à l'import, gardés dans la remarque « (code Excel : X) ».
    for d in Dispositif.objects.filter(type_dispositif__isnull=True, remarque__contains="(code Excel : ", **sin):
        m = re.search(r"\s*\(code Excel : ([^)]+)\)", d.remarque)
        if m and m.group(1) in CODES_S536:
            d.type_dispositif = m.group(1)
            d.remarque = (d.remarque[:m.start()] + d.remarque[m.end():]).strip()
            d.save(update_fields=["type_dispositif", "remarque"])

    for fiche in FicheLegende.objects.filter(**sin):
        dispositifs = {}
        for code, valeur in fiche.dispositifs.items():
            nouveau = LEGENDE_VERS_S536.get(code, code)
            dispositifs[nouveau if nouveau not in fiche.dispositifs else code] = valeur
        if dispositifs != fiche.dispositifs:
            fiche.dispositifs = dispositifs
            fiche.save(update_fields=["dispositifs"])


